const data = items[0].json;
const marche = data;
const client = data;
const qualification = data;

// ==========================================
// DONNÉES POUR TEMPLATES DOCXTEMPLATER
// ==========================================
const today = new Date();
const deadline = new Date(marche.parsedDeadline);
const daysLeft = Math.ceil((deadline - today) / (1000*60*60*24));

const templateData = {
  // --- Marché ---
  marche_reference: marche.reference,
  marche_title: marche.title,
  marche_amount: marche.parsedAmount.toLocaleString('fr-FR') + ' FCFA',
  marche_deadline: deadline.toLocaleDateString('fr-FR'),
  marche_days_left: daysLeft,
  marche_category: marche.category,
  marche_source: marche.source,
  marche_link: marche.link,

  // --- Client / Soumissionnaire ---
  client_name: client.company_name,
  client_rcm: client.rcm_number,
  client_ifu: client.ifu_number,
  client_address: client.address,
  client_phone: client.phone,
  client_email: client.email,
  client_legal_form: client.legal_form,
  client_capital: client.capital_social?.toLocaleString('fr-FR') + ' FCFA',
  client_representative: client.representative_name,
  client_rep_title: client.representative_title,

  // --- Capacités ---
  client_ca_3ans: client.ca_3_years?.map((y, i) => `${2024-i}: ${y.toLocaleString('fr-FR')} FCFA`).join(' | '),
  client_effectif: client.staff_count,
  client_tech_staff: client.tech_staff_count,
  client_refs: client.references?.map(r => `
    • ${r.year} - ${r.client} - ${r.description} - ${r.amount.toLocaleString('fr-FR')} FCFA`).join('') || 'À compléter',

  // --- Pièces Administratives (status) ---
  piece_rccm: qualification.checklist_json?.find(c => c.id === 'RCCM')?.status === 'ok' ? '✅ Fourni' : '❌ MANQUANT',
  piece_ifu: qualification.checklist_json?.find(c => c.id === 'IFU')?.status === 'ok' ? '✅ Fourni' : '❌ MANQUANT',
  piece_cnps: qualification.checklist_json?.find(c => c.id === 'CNPS')?.status === 'ok' ? '✅ Fourni' : '❌ MANQUANT',
  piece_impots: qualification.checklist_json?.find(c => c.id === 'IMPOTS')?.status === 'ok' ? '✅ Fourni' : '❌ MANQUANT',
  piece_licence: qualification.checklist_json?.find(c => c.id === 'LICENCE')?.status === 'ok' ? '✅ Fourni' : '❌ MANQUANT',
  piece_assurance: qualification.checklist_json?.find(c => c.id === 'ASSURANCE')?.status === 'ok' ? '✅ Fourni' : '❌ MANQUANT',

  // --- Calculs Financiers (Bordereau Prix) ---
  estimated_direct_cost: (marche.parsedAmount * 0.65).toLocaleString('fr-FR'),
  estimated_overhead: (marche.parsedAmount * 0.15).toLocaleString('fr-FR'),
  estimated_margin: (marche.parsedAmount * 0.20).toLocaleString('fr-FR'),

  // --- Dates ---
  date_jour: today.toLocaleDateString('fr-FR'),
  date_depot_limite: deadline.toLocaleDateString('fr-FR'),

  // --- Signatures ---
  rep_name: client.representative_name,
  rep_title: client.representative_title
};

return [{json: templateData}];

const files = items.map((item, i) => ({
  name: item.json.fileName || `doc_${i}.docx`,
  data: item.binary?.data || item.binary?.file
}));

// Créer ZIP (nécessite nodeJS zip ou commande shell)
// Ici on retourne juste les fichiers individuels
return files.map(f => ({json: {fileName: f.name, base64: f.data}}));
